// All implementations must embed UnimplementedCRMServiceServer
// for forward compatibility.
type CRMServiceServer interface {
	// Custom Fields
	CreateCustomField(context.Context, *CreateCustomFieldRequest) (*CreateCustomFieldResponse, error)
	GetCustomField(context.Context, *GetCustomFieldRequest) (*GetCustomFieldResponse, error)
	ListCustomFields(context.Context, *ListCustomFieldsRequest) (*ListCustomFieldsResponse, error)
	UpdateCustomField(context.Context, *UpdateCustomFieldRequest) (*UpdateCustomFieldResponse, error)
	DeleteCustomField(context.Context, *DeleteCustomFieldRequest) (*DeleteCustomFieldResponse, error)
	// Tags (Sprint 1)
	CreateTag(context.Context, *CreateTagRequest) (*CreateTagResponse, error)
	GetTag(context.Context, *GetTagRequest) (*GetTagResponse, error)
	ListTags(context.Context, *ListTagsRequest) (*ListTagsResponse, error)
	UpdateTag(context.Context, *UpdateTagRequest) (*UpdateTagResponse, error)
	DeleteTag(context.Context, *DeleteTagRequest) (*DeleteTagResponse, error)
	// Contacts (Sprint 2)
	CreateContact(context.Context, *CreateContactRequest) (*CreateContactResponse, error)
	GetContact(context.Context, *GetContactRequest) (*GetContactResponse, error)
	ListContacts(context.Context, *ListContactsRequest) (*ListContactsResponse, error)
	UpdateContact(context.Context, *UpdateContactRequest) (*UpdateContactResponse, error)
	DeleteContact(context.Context, *DeleteContactRequest) (*DeleteContactResponse, error)
	AddContactTags(context.Context, *AddContactTagsRequest) (*AddContactTagsResponse, error)
	RemoveContactTags(context.Context, *RemoveContactTagsRequest) (*RemoveContactTagsResponse, error)
	// Contact Import/Export (Phase 10)
	ImportContactsCSV(context.Context, *ImportContactsCSVRequest) (*ImportContactsResponse, error)
	ImportContactsVCard(context.Context, *ImportContactsVCardRequest) (*ImportContactsResponse, error)
	ImportContactsXLSX(context.Context, *ImportContactsXLSXRequest) (*ImportContactsResponse, error)
	ExportContactsCSV(context.Context, *ExportContactsCSVRequest) (*ExportContactsResponse, error)
	ExportContactsVCard(context.Context, *ExportContactsVCardRequest) (*ExportContactsResponse, error)
	PreviewImportCSV(context.Context, *PreviewImportCSVRequest) (*PreviewImportCSVResponse, error)
	UpdateContactVisibility(context.Context, *UpdateContactVisibilityRequest) (*UpdateContactVisibilityResponse, error)
	// Companies (Sprint 2)
	CreateCompany(context.Context, *CreateCompanyRequest) (*CreateCompanyResponse, error)
	GetCompany(context.Context, *GetCompanyRequest) (*GetCompanyResponse, error)
	ListCompanies(context.Context, *ListCompaniesRequest) (*ListCompaniesResponse, error)
	UpdateCompany(context.Context, *UpdateCompanyRequest) (*UpdateCompanyResponse, error)
	DeleteCompany(context.Context, *DeleteCompanyRequest) (*DeleteCompanyResponse, error)
	GetCompanyContacts(context.Context, *GetCompanyContactsRequest) (*GetCompanyContactsResponse, error)
	// Pipeline Stages (Sprint 3)
	CreatePipelineStage(context.Context, *CreatePipelineStageRequest) (*CreatePipelineStageResponse, error)
	GetPipelineStage(context.Context, *GetPipelineStageRequest) (*GetPipelineStageResponse, error)
	ListPipelineStages(context.Context, *ListPipelineStagesRequest) (*ListPipelineStagesResponse, error)
	UpdatePipelineStage(context.Context, *UpdatePipelineStageRequest) (*UpdatePipelineStageResponse, error)
	DeletePipelineStage(context.Context, *DeletePipelineStageRequest) (*DeletePipelineStageResponse, error)
	ReorderPipelineStages(context.Context, *ReorderPipelineStagesRequest) (*ReorderPipelineStagesResponse, error)
	// Deals (Sprint 3)
	CreateDeal(context.Context, *CreateDealRequest) (*CreateDealResponse, error)
	GetDeal(context.Context, *GetDealRequest) (*GetDealResponse, error)
	ListDeals(context.Context, *ListDealsRequest) (*ListDealsResponse, error)
	UpdateDeal(context.Context, *UpdateDealRequest) (*UpdateDealResponse, error)
	DeleteDeal(context.Context, *DeleteDealRequest) (*DeleteDealResponse, error)
	MoveDealToStage(context.Context, *MoveDealToStageRequest) (*MoveDealToStageResponse, error)
	AddDealTags(context.Context, *AddDealTagsRequest) (*AddDealTagsResponse, error)
	RemoveDealTags(context.Context, *RemoveDealTagsRequest) (*RemoveDealTagsResponse, error)
	// Activities (Sprint 4)
	CreateActivity(context.Context, *CreateActivityRequest) (*CreateActivityResponse, error)
	GetActivity(context.Context, *GetActivityRequest) (*GetActivityResponse, error)
	ListActivities(context.Context, *ListActivitiesRequest) (*ListActivitiesResponse, error)
	UpdateActivity(context.Context, *UpdateActivityRequest) (*UpdateActivityResponse, error)
	DeleteActivity(context.Context, *DeleteActivityRequest) (*DeleteActivityResponse, error)
	CompleteActivity(context.Context, *CompleteActivityRequest) (*CompleteActivityResponse, error)
	AddActivityTags(context.Context, *AddActivityTagsRequest) (*AddActivityTagsResponse, error)
	RemoveActivityTags(context.Context, *RemoveActivityTagsRequest) (*RemoveActivityTagsResponse, error)
	// Search (Sprint 4)
	Search(context.Context, *SearchRequest) (*SearchResponse, error)
	// Filters (Sprint 5)
	CreateSavedFilter(context.Context, *CreateSavedFilterRequest) (*CreateSavedFilterResponse, error)
	GetSavedFilter(context.Context, *GetSavedFilterRequest) (*GetSavedFilterResponse, error)
	ListSavedFilters(context.Context, *ListSavedFiltersRequest) (*ListSavedFiltersResponse, error)
	UpdateSavedFilter(context.Context, *UpdateSavedFilterRequest) (*UpdateSavedFilterResponse, error)
	DeleteSavedFilter(context.Context, *DeleteSavedFilterRequest) (*DeleteSavedFilterResponse, error)
	// Reports (Sprint 5)
	GetPipelineReport(context.Context, *GetPipelineReportRequest) (*GetPipelineReportResponse, error)
	GetConversionReport(context.Context, *GetConversionReportRequest) (*GetConversionReportResponse, error)
	GetActivityReport(context.Context, *GetActivityReportRequest) (*GetActivityReportResponse, error)
	// Duplicate Detection
	FindContactDuplicates(context.Context, *FindContactDuplicatesRequest) (*FindContactDuplicatesResponse, error)
	MergeContacts(context.Context, *MergeContactsRequest) (*MergeContactsResponse, error)
	FindCompanyDuplicates(context.Context, *FindCompanyDuplicatesRequest) (*FindCompanyDuplicatesResponse, error)
	MergeCompanies(context.Context, *MergeCompaniesRequest) (*MergeCompaniesResponse, error)
	// Contact Timeline
	GetContactTimeline(context.Context, *GetContactTimelineRequest) (*GetContactTimelineResponse, error)
	// Contact Deletion Impact Preview
	PreviewContactDeletion(context.Context, *PreviewContactDeletionRequest) (*PreviewContactDeletionResponse, error)
	// GDPR Consent Management
	GetContactConsents(context.Context, *GetContactConsentsRequest) (*GetContactConsentsResponse, error)
	GrantConsent(context.Context, *GrantConsentRequest) (*GrantConsentResponse, error)
	RevokeConsent(context.Context, *RevokeConsentRequest) (*RevokeConsentResponse, error)
	GetConsentHistory(context.Context, *GetConsentHistoryRequest) (*GetConsentHistoryResponse, error)
	RequestDeletion(context.Context, *RequestDeletionRequest) (*RequestDeletionResponse, error)
	ProcessDeletion(context.Context, *ProcessDeletionRequest) (*ProcessDeletionResponse, error)
	// Advisory Protocols (Beratungsprotokolle — P8)
	CreateAdvisoryProtocol(context.Context, *CreateAdvisoryProtocolRequest) (*CreateAdvisoryProtocolResponse, error)
	GetAdvisoryProtocol(context.Context, *GetAdvisoryProtocolRequest) (*GetAdvisoryProtocolResponse, error)
	ListAdvisoryProtocols(context.Context, *ListAdvisoryProtocolsRequest) (*ListAdvisoryProtocolsResponse, error)
	UpdateAdvisoryProtocol(context.Context, *UpdateAdvisoryProtocolRequest) (*UpdateAdvisoryProtocolResponse, error)
	DeleteAdvisoryProtocol(context.Context, *DeleteAdvisoryProtocolRequest) (*DeleteAdvisoryProtocolResponse, error)
	HandOverAdvisoryProtocol(context.Context, *HandOverAdvisoryProtocolRequest) (*HandOverAdvisoryProtocolResponse, error)
	GenerateAdvisoryProtocolPDF(context.Context, *GenerateAdvisoryProtocolPDFRequest) (*GenerateAdvisoryProtocolPDFResponse, error)
	GetReferralReport(context.Context, *GetReferralReportRequest) (*GetReferralReportResponse, error)
	// Leads (contact lifecycle stage, not a separate entity)
	ListLeads(context.Context, *ListLeadsRequest) (*ListLeadsResponse, error)
	CreateLead(context.Context, *CreateLeadRequest) (*CreateLeadResponse, error)
	UpdateLead(context.Context, *UpdateLeadRequest) (*UpdateLeadResponse, error)
	ConvertLead(context.Context, *ConvertLeadRequest) (*ConvertLeadResponse, error)
	PromoteContactToLead(context.Context, *PromoteContactToLeadRequest) (*PromoteContactToLeadResponse, error)
	mustEmbedUnimplementedCRMServiceServer()
}

